#[cfg(all(test, target_os = "linux"))]
mod independent_review_probes {
    use super::*;
    use crate::generated::{FileHeader, ResumeSettings, SessionOpen, TransferRole};
    use crate::remote::transfer::payload::PreparedPayload;
    use crate::remote::transfer::sink::{FsTransferSink, FsSinkConfig, TransferSink, METADATA_TAIL_FAULT_PREFIXES};
    use crate::remote::transfer::source::FsTransferSource;
    use crate::transfer_session::{DestinationSessionConfig, DestinationTarget, SessionEndpoint, SourceSessionConfig, run_destination, run_source, transport};
    use std::os::unix::fs::{FileTypeExt, PermissionsExt};
    use std::sync::Arc;

    fn header() -> FileHeader {
        FileHeader { relative_path: "item".into(), size: 8, permissions: 0o644, ..Default::default() }
    }

    #[tokio::test]
    async fn absent_destination_on_failed_validation() {
        let root = tempfile::tempdir().unwrap();
        let src = root.path().join("src");
        let dst = root.path().join("dst");
        fs::create_dir(&src).unwrap();
        fs::create_dir(&dst).unwrap();
        fs::write(src.join("item"), b"8 bytes!").unwrap();
        let path = dst.join("item");
        CREATE_LOOK_FAULTS.lock().unwrap().push(path.clone());
        let sink = FsTransferSink::new(src, dst, FsSinkConfig::default());
        let outcome = sink.write_payload(PreparedPayload::File(header())).await.unwrap();
        CREATE_LOOK_FAULTS.lock().unwrap().retain(|p| p != &path);
        let left = fs::metadata(&path).ok().map(|m|m.len());
        assert_eq!(outcome.files_failed_total, 1);
        assert!(left.is_none() || outcome.failures[0].reason.contains(crate::remote::transfer::sink::INCOMPLETE_LEFT_IN_PLACE), "length={left:?}, failure={:?}", outcome.failures);
    }

    #[tokio::test]
    async fn cleanup_after_readonly_mode_applied() {
        let root = tempfile::tempdir().unwrap();
        let src = root.path().join("src");
        let dst = root.path().join("dst");
        fs::create_dir(&src).unwrap();
        fs::create_dir(&dst).unwrap();
        let path = dst.join("item");
        fs::write(src.join("item"), b"8 bytes!").unwrap();
        fs::set_permissions(src.join("item"), fs::Permissions::from_mode(0o444)).unwrap();
        fs::write(&path, b"old").unwrap();
        fs::set_permissions(&dst, fs::Permissions::from_mode(0o555)).unwrap();
        METADATA_TAIL_FAULT_PREFIXES.lock().unwrap().push(path.clone());
        let sink = FsTransferSink::new(src, dst.clone(), FsSinkConfig::default());
        let outcome = sink.write_payload(PreparedPayload::File(header())).await.unwrap();
        METADATA_TAIL_FAULT_PREFIXES.lock().unwrap().retain(|p| p != &path);
        fs::set_permissions(&dst, fs::Permissions::from_mode(0o755)).unwrap();
        assert_eq!(outcome.files_failed_total, 1);
        assert_eq!(fs::metadata(&path).unwrap().len(), 9, "{:?}",outcome.failures);
    }

    #[test]
    fn public_path_copy_device_source() {
        let root = tempfile::tempdir().unwrap();
        let source = Path::new("/dev/null");
        let ordinary = copy_file(source, &root.path().join("plain"), &BufferSizer::default(), false).is_err();
        let resume = resume_copy_file(source, &root.path().join("resume"), 1024).is_err();
        let mmap = mmap_copy_file(source, &root.path().join("mmap")).is_err();
        assert_eq!((ordinary, resume, mmap), (true, true, true), "each opener should refuse the device");
    }

    #[tokio::test]
    async fn wire_resume_at_existing_fifo() {
        let root = tempfile::tempdir().unwrap();
        let src = root.path().join("src");
