#[cfg(all(test, unix))]
mod independent_record_observation {
    use std::fs;
    use crate::generated::FileHeader;
    use crate::remote::transfer::payload::PreparedPayload;
    use crate::remote::transfer::sink::{FsSinkConfig, FsTransferSink, TransferSink, INCOMPLETE_LEFT_IN_PLACE};

    #[tokio::test]
    async fn source_failure_with_a_diagnostic_phrase_in_the_path() {
        let tmp = tempfile::tempdir().unwrap();
        let src = tmp.path().join("src");
        let dst = tmp.path().join("dst");
        let name = INCOMPLETE_LEFT_IN_PLACE;
        fs::create_dir_all(src.join(name)).unwrap();
        fs::create_dir(&dst).unwrap();
        let header = FileHeader { relative_path: name.to_owned(), size: 5, ..Default::default() };
        let sink = FsTransferSink::new(src, dst.clone(), FsSinkConfig::default());
        let result = sink.write_payload(PreparedPayload::File(header)).await.unwrap();
        assert!(result.file_failed(name));
        assert!(!dst.join(name).exists());
        assert!(result.wire_left_in_place().0.is_empty(), "claimed leftover = {:?} for {:?}", result.wire_left_in_place(), result.failures);
    }
}
